export interface Receipt { id: number; tenant: string; key: string; cents: number }
export class Ledger {
  readonly entries: Receipt[] = [];
  // Idempotency records scoped by tenant and key.
  private readonly byScope = new Map<string, Receipt>();
  async apply(tenant: string, key: string, cents: number): Promise<Receipt> {
    // No await before the check-and-insert below, so concurrent calls are serialized.
    const scope = JSON.stringify([tenant, key]);
    const existing = this.byScope.get(scope);
    if (existing) {
      if (existing.cents !== cents) throw new Error('key conflict');
      return existing;
    }
    const receipt: Receipt = { id: this.entries.length + 1, tenant, key, cents };
    this.byScope.set(scope, receipt);
    this.entries.push(receipt);
    return receipt;
  }
}

